CREATE TABLE users (id CHAR(36) PRIMARY KEY,email VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,provider VARCHAR(30),provider_user_id VARCHAR(255),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE contracts (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,category VARCHAR(50) NOT NULL,provider_name VARCHAR(200),status VARCHAR(30) NOT NULL DEFAULT 'PENDING_VERIFICATION',source_type VARCHAR(30) NOT NULL,contract_start_date DATE,contract_end_date DATE,auto_renewal_date DATE,cancellation_deadline DATE,monthly_amount DECIMAL(15,2),currency CHAR(3) NOT NULL DEFAULT 'KRW',penalty_amount DECIMAL(15,2),cancellation_terms TEXT,plain_summary TEXT,risk_level VARCHAR(20),amount_verified BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id),CHECK(status IN ('ACTIVE','EXPIRED','CANCELLED','PENDING_VERIFICATION')),CHECK(source_type IN ('PHOTO','PDF','HWP','DOCS','IMAGE','MANUAL','PAYMENT_SUGGESTION')),CHECK(risk_level IS NULL OR risk_level IN ('LOW','MEDIUM','HIGH')),CHECK(monthly_amount IS NULL OR monthly_amount>=0),CHECK(contract_end_date IS NULL OR contract_start_date IS NULL OR contract_end_date>=contract_start_date)) ENGINE=InnoDB;
CREATE TABLE documents (id CHAR(36) PRIMARY KEY,contract_id CHAR(36) NOT NULL,document_type VARCHAR(30) NOT NULL,original_filename VARCHAR(255) NOT NULL,storage_key VARCHAR(500) NOT NULL UNIQUE,content_type VARCHAR(100),file_size BIGINT,checksum VARCHAR(128),is_primary BOOLEAN NOT NULL DEFAULT FALSE,uploaded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted_at DATETIME NULL,FOREIGN KEY(contract_id) REFERENCES contracts(id),CHECK(file_size IS NULL OR file_size>0)) ENGINE=InnoDB;
CREATE TABLE ai_analyses (id CHAR(36) PRIMARY KEY,document_id CHAR(36) NOT NULL,analysis_version VARCHAR(50) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'QUEUED',ocr_text LONGTEXT,masked_text LONGTEXT,extracted_data JSON,confidence DECIMAL(5,4),error_message TEXT,requested_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL,FOREIGN KEY(document_id) REFERENCES documents(id),CHECK(status IN ('QUEUED','PROCESSING','COMPLETED','FAILED')),CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1)) ENGINE=InnoDB;
CREATE TABLE contract_schedules (id CHAR(36) PRIMARY KEY,contract_id CHAR(36) NOT NULL,schedule_type VARCHAR(30) NOT NULL,due_date DATE NOT NULL,action_title VARCHAR(200) NOT NULL,action_description TEXT,reminder_days_before INT NOT NULL DEFAULT 14,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',completed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(contract_id) REFERENCES contracts(id),CHECK(schedule_type IN ('RENEWAL','CANCELLATION','PAYMENT','EXPIRY','CUSTOM')),CHECK(status IN ('PENDING','COMPLETED','DISMISSED')),CHECK(reminder_days_before>=0)) ENGINE=InnoDB;
CREATE TABLE payment_detection_events (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,merchant_name VARCHAR(200) NOT NULL,amount DECIMAL(15,2) NOT NULL,paid_at DATETIME NOT NULL,source_package VARCHAR(255) NOT NULL,parser_version VARCHAR(50),confidence DECIMAL(5,4),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),CHECK(amount>=0),CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1)) ENGINE=InnoDB;
CREATE TABLE payment_transactions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,contract_id CHAR(36),detection_event_id CHAR(36),source VARCHAR(30) NOT NULL DEFAULT 'ANDROID_NOTIFICATION',merchant_name VARCHAR(200) NOT NULL,amount DECIMAL(15,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'KRW',paid_at DATETIME NOT NULL,recurring_hint BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(detection_event_id) REFERENCES payment_detection_events(id),UNIQUE KEY uk_payment_detection(detection_event_id),CHECK(source IN ('ANDROID_NOTIFICATION','MANUAL')),CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE contract_suggestions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,merchant_name VARCHAR(200) NOT NULL,category VARCHAR(50),estimated_amount DECIMAL(15,2),estimated_cycle VARCHAR(30),detection_count INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',contract_id CHAR(36),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,responded_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id),CHECK(status IN ('PENDING','ACCEPTED','REJECTED','IGNORED','EXPIRED')),CHECK(estimated_amount IS NULL OR estimated_amount>=0)) ENGINE=InnoDB;
CREATE TABLE notifications (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,contract_id CHAR(36),schedule_id CHAR(36),suggestion_id CHAR(36),notification_type VARCHAR(30) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,scheduled_at DATETIME NOT NULL,sent_at DATETIME NULL,read_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id),FOREIGN KEY(schedule_id) REFERENCES contract_schedules(id),FOREIGN KEY(suggestion_id) REFERENCES contract_suggestions(id)) ENGINE=InnoDB;
CREATE TABLE chat_sessions (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,contract_id CHAR(36),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(contract_id) REFERENCES contracts(id)) ENGINE=InnoDB;
CREATE TABLE chat_messages (id CHAR(36) PRIMARY KEY,session_id CHAR(36) NOT NULL,role VARCHAR(20) NOT NULL,content LONGTEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(session_id) REFERENCES chat_sessions(id),CHECK(role IN ('USER','ASSISTANT','SYSTEM'))) ENGINE=InnoDB;
CREATE INDEX idx_contracts_user_status ON contracts(user_id,status,deleted_at);
CREATE INDEX idx_contracts_schedule_dates ON contracts(auto_renewal_date,cancellation_deadline,deleted_at);
CREATE INDEX idx_documents_contract ON documents(contract_id,deleted_at);
CREATE INDEX idx_ai_analyses_document_status ON ai_analyses(document_id,status,requested_at);
CREATE INDEX idx_schedules_due_status ON contract_schedules(due_date,status);
CREATE INDEX idx_detection_user_paid ON payment_detection_events(user_id,paid_at DESC);
CREATE INDEX idx_detection_merchant_paid ON payment_detection_events(user_id,merchant_name,paid_at DESC);
CREATE INDEX idx_detection_merchant_amount ON payment_detection_events(user_id,merchant_name,amount,paid_at);
CREATE INDEX idx_payments_user_paid ON payment_transactions(user_id,paid_at DESC);
CREATE INDEX idx_payments_contract_paid ON payment_transactions(contract_id,paid_at DESC);
CREATE INDEX idx_suggestions_user_status ON contract_suggestions(user_id,status,created_at DESC);
CREATE INDEX idx_suggestions_merchant_status ON contract_suggestions(user_id,merchant_name,status);
CREATE INDEX idx_notifications_unread ON notifications(user_id,read_at,scheduled_at);
CREATE INDEX idx_chat_messages_session_created ON chat_messages(session_id,created_at);